"""The season the planner reads: typed, immutable, and only the columns the planner uses."""

from __future__ import annotations

from dataclasses import dataclass

WEEKS_PER_MONTH = 4
DEFER_WEEKS = 26        # an untrimmed circuit waits this many weeks past the season for the next one

Weeks = tuple[tuple[int, int], ...]     # spans of weeks, each (first, last), both included


@dataclass(frozen=True)
class Circuit:
    cid: str
    region: str
    miles: int
    cost: int           # $k to trim the circuit
    risk: int           # $k a year of tree-caused outage risk that a trim removes
    weeks: int          # crew-weeks of work to trim it
    growth: float       # $k a week by which the weekly risk grows while the circuit waits
    windows: Weeks      # the trim must lie inside one of these; () means the whole season
    must: bool          # compliance: it must be trimmed this season

    def carried(self, end: int) -> int:
        """$k of risk carried from week 0 until a trim that ends at `end` (weeks 0 to end - 1)."""
        weekly = self.risk / 52
        return round(weekly * end + self.growth * end * (end - 1) / 2)


@dataclass(frozen=True)
class Season:
    name: str
    budget: int         # $k for the year's trimming
    crews: int          # crews working the season
    months: int         # months in the season, each WEEKS_PER_MONTH weeks
    crew_off: dict[str, Weeks]      # crew id -> weeks it cannot work
    circuits: tuple[Circuit, ...]

    def circuit(self, cid: str) -> Circuit:
        return next(c for c in self.circuits if c.cid == cid)


@dataclass(frozen=True)
class Override:
    """A planner's decision the plan must keep: pin a trim, skip a circuit, or force one in."""
    kind: str                       # "pin", "skip" or "force"
    cid: str
    crew: str | None = None         # pin: this crew (None: any crew)
    start: int | None = None        # pin: this first week (None: any week)
    reason: str = ""

    def says(self) -> str:
        where = "".join([f" on {self.crew}" if self.crew else "", f" from week {self.start}"
                         if self.start is not None else ""])
        what = {"pin": f"trim {self.cid}{where}", "skip": f"leave {self.cid} for next season",
                "force": f"trim {self.cid} this season"}[self.kind]
        return f"{what} ({self.reason or 'no reason given'})"


def spans(raw: list) -> Weeks:
    return tuple((int(first), int(last)) for first, last in raw)


def season_from_dict(raw: dict) -> Season:
    """Read the columns the planner uses. Columns it does not use yet are ignored.

    A circuit with no windows may be trimmed in any week, one with no must flag is optional work,
    and a season with no crew_off has every crew at work every week.
    """
    circuits = tuple(Circuit(c["id"], c["region"], int(c["miles"]), int(c["cost"]), int(c["risk"]),
                             int(c["weeks"]), float(c["growth"]), spans(c.get("windows") or []),
                             bool(c.get("must", False)))
                     for c in raw["circuits"])
    crew_off = {k: spans(weeks) for k, weeks in (raw.get("crew_off") or {}).items()}
    return Season(raw.get("name", "season"), int(raw["budget"]), int(raw["crews"]), int(raw["months"]),
                  crew_off, circuits)

"""A seeded generator of fictional trimming seasons, in the shape the circuit inventory exports.

Each column is drawn from its own random stream, named after the seed, the size and the column, so
adding a column later never changes the values of the columns already there.
"""

from __future__ import annotations

import math
import random

SIZES = {"tiny": 6, "small": 20, "medium": 60}
CREWS = {"tiny": 1, "small": 2, "medium": 6}
MONTHS = 6                                                     # April to September
REGIONS = ("North", "River", "Hills")


def stream(seed: int, size: str, column: str) -> random.Random:
    return random.Random(f"{seed}-{size}-{column}")


def scenario(size: str = "small", seed: int = 54) -> dict:
    """One season: a budget and the circuits, as plain JSON-ready values."""
    n = SIZES[size]
    draw = stream(seed, size, "circuits")
    circuits = []
    for i in range(1, n + 1):
        miles = draw.randint(8, 40)
        circuits.append({
            "id": f"C{i:02d}",
            "region": draw.choice(REGIONS),
            "miles": miles,
            "cost": round(miles * draw.uniform(3.0, 6.0)),       # $k to trim the whole circuit
            "risk": round(miles * draw.uniform(2.0, 12.0)),      # $k a year of tree-caused outage risk
        })
    work = stream(seed, size, "weeks")
    for c in circuits:
        c["weeks"] = math.ceil(c["miles"] / work.uniform(4.0, 7.0))     # crew-weeks to trim it
    growth = stream(seed, size, "growth")
    for c in circuits:
        c["growth"] = round(c["risk"] / 52 * growth.uniform(0.02, 0.10), 2)   # $k a week, every week
    access = stream(seed, size, "access")
    last = MONTHS * 4 - 1
    for c in circuits:
        c["must"] = access.random() < 0.15                     # overdue on its cycle: trim it this season
        if c["region"] == "River":
            c["windows"] = [[8, last]]                         # wet ground: no equipment before week 8
        elif c["region"] == "Hills" and access.random() < 0.5:
            c["windows"] = [[0, 5], [14, last]]                # nesting season closes weeks 6 to 13
        else:
            c["windows"] = []                                  # the whole season
    crew_off = {"K1": [[10, 11]]}                              # training
    if CREWS[size] > 1:
        crew_off[f"K{CREWS[size]}"] = [[14, 17]]               # held back for storm duty
    budget = round(0.45 * sum(c["cost"] for c in circuits))
    return {"name": f"{size}-{seed}", "budget": budget, "crews": CREWS[size], "months": MONTHS,
            "crew_off": crew_off, "circuits": circuits}

"""Turn a season into a plan: each trim is one crew's run of consecutive weeks, scheduled by CP-SAT
to carry the least risk, keeping every calendar, must and planner's override, or saying why it cannot."""

from __future__ import annotations

from dataclasses import dataclass, field

from ortools.sat.python import cp_model

from vegcrew.data import Override, Season
from vegcrew.explain import why_infeasible
from vegcrew.model import build, crew_ids, horizon

TIME_LIMIT = 10.0                                   # seconds
WORKERS = 4                                         # parallel search workers

__all__ = ["Plan", "Trim", "check_overrides", "crew_ids", "horizon", "make_plan"]


@dataclass(frozen=True)
class Trim:
    cid: str
    crew: str                                       # K1, K2, ...
    start: int                                      # first week, counted from 0
    end: int                                        # the week after the last: end - start = weeks


@dataclass(frozen=True)
class Plan:
    status: str                                     # OPTIMAL, FEASIBLE, INFEASIBLE, UNKNOWN or MODEL_INVALID
    trims: dict[str, Trim] = field(default_factory=dict)
    cost: int = 0                                   # $k spent
    risk_removed: int = 0                           # $k a year of risk the trims remove
    risk_carried: int = 0                           # $k of risk carried until each circuit is trimmed
    explanation: tuple[str, ...] = ()               # INFEASIBLE: the rules that cannot all hold


def check_overrides(season: Season, overrides: tuple[Override, ...]) -> list[str]:
    """What is wrong with the overrides as data, before any model is built."""
    problems = []
    ids = {c.cid for c in season.circuits}
    for i, o in enumerate(overrides, start=1):
        if o.kind not in ("pin", "skip", "force"):
            problems.append(f"override {i}: unknown kind {o.kind!r}")
        if o.cid not in ids:
            problems.append(f"override {i}: no circuit {o.cid}")
        if o.crew is not None and o.crew not in crew_ids(season):
            problems.append(f"override {i}: no crew {o.crew}")
        if o.start is not None and not 0 <= o.start < horizon(season):
            problems.append(f"override {i}: week {o.start} is outside the season")
    return problems


def make_plan(season: Season, overrides: tuple[Override, ...] = ()) -> Plan:
    """Choose the circuits to trim, the crew for each and its weeks: the least risk carried through the
    season and the wait for the next, within the budget, one crew per trim, one trim per crew at a time,
    every trim inside one of its circuit's windows and outside its crew's weeks off, every must trimmed,
    every override kept. If no plan keeps every rule, say which of the planner's rules clash."""
    problems = check_overrides(season, overrides)
    if problems:
        raise ValueError("; ".join(problems))
    tm = build(season, overrides)
    tm.model.add_bool_and(list(tm.rules.values()))     # every rule holds
    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = TIME_LIMIT
    solver.parameters.num_workers = WORKERS
    status = solver.status_name(solver.solve(tm.model))
    if status == "INFEASIBLE":
        return Plan(status, explanation=tuple(why_infeasible(season, overrides)))
    if status not in ("OPTIMAL", "FEASIBLE"):
        return Plan(status)
    trims = {}
    for (cid, k), p in tm.present.items():
        if solver.boolean_value(p):
            start = solver.value(tm.start[cid, k])
            trims[cid] = Trim(cid, k, start, start + season.circuit(cid).weeks)
    chosen = [season.circuit(cid) for cid in trims]
    return Plan(status, trims, cost=sum(c.cost for c in chosen), risk_removed=sum(c.risk for c in chosen),
                risk_carried=round(solver.objective_value))

